-- An assistant reply drawn as an A2UI layout. `text` keeps the reply's plain-text summary, so search, copy,
-- compaction and model history read layout parts like text parts.
ALTER TABLE {{schema}}.tf_conversation_parts
  ADD COLUMN layout jsonb,
  ADD CONSTRAINT tf_conversation_parts_layout CHECK (
    layout IS NULL OR (
      kind = 'layout'
      AND jsonb_typeof(layout) = 'object'
      AND layout->>'protocol' = 'a2ui/0.9'
      AND layout->>'placement' IN ('chat', 'canvas')
      AND jsonb_typeof(layout->'messages') = 'array'
      AND octet_length(layout::text) <= 262144
    )
  ),
  DROP CONSTRAINT tf_conversation_parts_kind_check,
  ADD CONSTRAINT tf_conversation_parts_kind_check CHECK ((((kind = 'text'::text) AND (text IS NOT NULL) AND (attachment_id IS NULL) AND (request_id IS NULL) AND (response_id IS NULL) AND (approval_id IS NULL) AND (file_id IS NULL) AND (google_file IS NULL) AND (skill_id IS NULL) AND (compaction_id IS NULL)) OR ((kind = 'attachment'::text) AND (text IS NULL) AND (attachment_id IS NOT NULL) AND (request_id IS NULL) AND (response_id IS NULL) AND (approval_id IS NULL) AND (file_id IS NULL) AND (google_file IS NULL) AND (skill_id IS NULL) AND (compaction_id IS NULL)) OR ((kind = 'request'::text) AND (text IS NULL) AND (attachment_id IS NULL) AND (request_id IS NOT NULL) AND (response_id IS NULL) AND (approval_id IS NULL) AND (file_id IS NULL) AND (google_file IS NULL) AND (skill_id IS NULL) AND (compaction_id IS NULL)) OR ((kind = 'response'::text) AND (text IS NULL) AND (attachment_id IS NULL) AND (request_id IS NULL) AND (response_id IS NOT NULL) AND (approval_id IS NULL) AND (file_id IS NULL) AND (google_file IS NULL) AND (skill_id IS NULL) AND (compaction_id IS NULL)) OR ((kind = ANY (ARRAY['approval'::text, 'approval-resolution'::text])) AND (text IS NULL) AND (attachment_id IS NULL) AND (request_id IS NULL) AND (response_id IS NULL) AND (approval_id IS NOT NULL) AND (file_id IS NULL) AND (google_file IS NULL) AND (skill_id IS NULL) AND (compaction_id IS NULL)) OR ((kind = 'file'::text) AND (text IS NULL) AND (attachment_id IS NULL) AND (request_id IS NULL) AND (response_id IS NULL) AND (approval_id IS NULL) AND (file_id IS NOT NULL) AND (google_file IS NULL) AND (skill_id IS NULL) AND (compaction_id IS NULL)) OR ((kind = 'google-file'::text) AND (text IS NULL) AND (attachment_id IS NULL) AND (request_id IS NULL) AND (response_id IS NULL) AND (approval_id IS NULL) AND (file_id IS NULL) AND (skill_id IS NULL) AND (compaction_id IS NULL) AND (jsonb_typeof(google_file) = 'object'::text) AND (google_file ?& ARRAY['fileId'::text, 'integrationId'::text, 'accountId'::text, 'generation'::text, 'name'::text, 'mimeType'::text]) AND (octet_length((google_file)::text) <= 4096)) OR ((kind = ANY (ARRAY['skill'::text, 'skill-use'::text])) AND (text IS NULL) AND (attachment_id IS NULL) AND (request_id IS NULL) AND (response_id IS NULL) AND (approval_id IS NULL) AND (file_id IS NULL) AND (google_file IS NULL) AND (skill_id IS NOT NULL) AND (compaction_id IS NULL)) OR ((kind = 'compact'::text) AND (attachment_id IS NULL) AND (request_id IS NULL) AND (response_id IS NULL) AND (approval_id IS NULL) AND (file_id IS NULL) AND (google_file IS NULL) AND (skill_id IS NULL) AND ((text IS NULL) OR (compaction_id IS NULL)) AND (char_length(COALESCE(text, 'x'::text)) <= 2000)) OR ((kind = 'compaction'::text) AND (text IS NULL) AND (attachment_id IS NULL) AND (request_id IS NULL) AND (response_id IS NULL) AND (approval_id IS NULL) AND (file_id IS NULL) AND (google_file IS NULL) AND (skill_id IS NULL) AND (compaction_id IS NOT NULL)) OR ((kind = 'layout'::text) AND (text IS NOT NULL) AND (layout IS NOT NULL) AND (attachment_id IS NULL) AND (request_id IS NULL) AND (response_id IS NULL) AND (approval_id IS NULL) AND (file_id IS NULL) AND (google_file IS NULL) AND (skill_id IS NULL) AND (compaction_id IS NULL))));
